 private static final BlockPos POS=new BlockPos(22800,84,22800),SAVE=POS.east(5),INERT=POS.east(7);private static Fixture full,slab;private static NativeRampBlock housingFull;private static NativeRampSlabBlock housingSlab;private static Block probe;private static BlockEntityType<NativeRampEntity> type;private static int checks,probes;private static boolean observing;
 private static boolean enabled(){return System.getProperty("vandorlabs.transmitterPhase","").startsWith("ramp-host-");}private static void need(boolean ok,String text){checks++;if(!ok)throw new AssertionError("Ramp host: "+text);}
