 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;event.register(Registries.BLOCK,h->{full=new Fixture();slab=new Fixture();h.register(ResourceLocation.parse("vandorlabs:ramp_host_full"),full);h.register(ResourceLocation.parse("vandorlabs:ramp_host_slab"),slab);housingFull=new NativeRampBlock(BlockBehaviour.Properties.of().strength(1),()->type);housingSlab=new NativeRampSlabBlock(BlockBehaviour.Properties.of().strength(1),()->type);h.register(ResourceLocation.parse("vandorlabs:ramp_housing_full"),housingFull);h.register(ResourceLocation.parse("vandorlabs:ramp_housing_slab"),housingSlab);probe=new Block(BlockBehaviour.Properties.of().isRedstoneConductor((s,w,p)->false)){@Override protected boolean isSignalSource(BlockState state){return true;}@Override protected int getSignal(BlockState state,BlockGetter level,BlockPos pos,Direction side){probes++;return 7;}@Override protected int getDirectSignal(BlockState state,BlockGetter level,BlockPos pos,Direction side){probes++;return 7;}};h.register(ResourceLocation.parse("vandorlabs:ramp_host_probe"),probe);});event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.<NativeRampEntity>of(Host::new,full,slab,housingFull,housingSlab).build(null);h.register(ResourceLocation.parse("vandorlabs:ramp_host_fixture"),type);});}}
