 private static final class Source implements NativeChannelMember {final Host owner;Source(Host owner){this.owner=owner;}public BlockEntity channelBlockEntity(){return owner;}public ChannelList getRedstoneChannels(){return ChannelList.of(73101);}public ChannelList transmittedChannels(){return getRedstoneChannels();}public int transmissionRange(){return 16;}public int localSignalLevel(int c){return 15;}public void setChannelLevel(int n){}}
 private static void write(ServerLevel w)throws Exception {NativeRampAuthorizationChecks.write(w,housingFull);if(System.getProperty("vandorlabs.rampGenerationReference")!=null)NativeRampCaptureChecks.run(w,housingFull,housingSlab,Path.of(System.getProperty("vandorlabs.rampGenerationReference")));NativeRampHousingChecks.run(Path.of(System.getProperty("vandorlabs.rampSettingsReference")),housingFull,housingSlab);var housingPos=POS.south(4);w.getChunkAt(housingPos);var initial=housingSlab.defaultBlockState().setValue(NativeRampBlock.FACING,Direction.EAST).setValue(NativeRampBlock.ACTIVE_FACE,Direction.UP).setValue(NativeRampSlabBlock.HALF,net.minecraft.world.level.block.state.properties.Half.TOP);w.setBlock(housingPos,initial,18);Host housing=at(w,housingPos);var choices=new CompoundTag();NativeRampSettings.defaults().writeChoices(choices);choices.putBoolean("MoatMode",true);housing.loadWithComponents(choices,w.registryAccess());int beforeLoadProbes=probes;housing.onLoad();need(w.getBlockState(housingPos)==initial&&probes==beforeLoadProbes,"housing load/onLoad local-only");NativeRedstoneChannels.flush(w);need(w.getBlockState(housingPos).getValue(NativeRampBlock.MODE)==6&&!w.getBlockState(housingPos).getValue(NativeRampBlock.ACTIVE),"deferred listed mode publication");need(housing.horizontalFacing()==Direction.EAST&&housing.scanFacing()==Direction.UP&&housing.slab(),"owning scan/travel getters stay distinct");need(NativeRampBlock.updateModelState(housing,true)&&w.getBlockState(housingPos).getValue(NativeRampBlock.ACTIVE),"owning listed activity publication");w.setBlock(housingPos,Blocks.AIR.defaultBlockState(),18);int count=0;try(var lines=new BufferedReader(new InputStreamReader(new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.rampSettingsReference")))),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=lines.readLine())!=null){var row=JsonParser.parseString(line).getAsJsonObject();var input=TagParser.parseTag(row.get("input").getAsString());input.putString("PrivateRampMarker","private:ramp");input.putByteArray("OpaqueRampPayload",new byte[65536]);Host owner=put(w,POS,row.get("block").getAsString().endsWith("_slab"),row.get("fresh").getAsBoolean()?null:input);if(row.get("fresh").getAsBoolean())input=null;need(!owner.inert(),"usable Source settings case="+count);var snapshot=row.getAsJsonObject("snapshot");int facing=snapshot.get("travelFacing").getAsInt();need(owner.settings().capture(facing).equals(TagParser.parseTag(snapshot.get("capture").getAsString())),"Source capture case="+count);var saved=owner.saveWithoutMetadata(w.registryAccess());need(NativeRampSettings.read(saved).equals(owner.settings()),"choice save roundtrip case="+count);if(input!=null)need(saved.getByteArray("OpaqueRampPayload").length==65536&&saved.getString("PrivateRampMarker").equals("private:ramp"),"opaque success retention case="+count);var dto=owner.getUpdateTag(w.registryAccess());need(!dto.contains("OpaqueRampPayload")&&!dto.contains("Sources")&&!dto.contains("Owner")&&!dto.toString().contains("private:ramp"),"explicit public choices case="+count);count++;}}need(count==256,"all Source cases");
  var receipt=new NativeRampReceipt(true,true,true,false,new NativeRampMenu.Status("Preparing",false,true,false,1));need(receipt.outcome(NativeRampSettings.defaults()).actionPending()&&!receipt.activationRefused(),"pending item receipt is not refused");
  var tag=new CompoundTag();tag.putIntArray("RedstoneChannels",new int[]{73101});tag.putString("PrivateRampMarker","saved");tag.putByteArray("OpaqueRampPayload",new byte[65536]);Host owner=put(w,SAVE,true,tag);var initialItem=owner.itemSettings();need(!initialItem.contains("PrivateRampMarker")&&!initialItem.contains("OpaqueRampPayload")&&!initialItem.contains("NativeRampSchema"),"item carries only choices");try{owner.installItemChoices(NativeRampSettings.defaults());throw new AssertionError("unguarded item install");}catch(IllegalStateException expected){}need(owner.settings().channels().equals(ChannelList.of(73101)),"unguarded install leaves choices intact");w.setBlock(SAVE.north(),probe.defaultBlockState(),18);probes=0;owner.onLoad();need(probes==0,"local-only onLoad");NativeRedstoneChannels.flush(w);need(probes>0&&owner.visual().physicalPower()==7,"deferred physical sampling");Source source=new Source(owner);NativeRedstoneChannels.channelsChanged(source);need(owner.visual().receivedPower()==15,"receive channel");NativeRedstoneChannels.unregister(source);need(owner.visual().receivedPower()==0&&owner.visual().physicalPower()==7,"withdrawal keeps physical input");var visual=owner.visual();need(java.util.concurrent.CompletableFuture.supplyAsync(()->{owner.beforeChannelRegistration();return owner.visual();}).join()==visual,"worker refuses world sampling");
  owner.onChunkUnloaded();NativeRedstoneChannels.channelsChanged(source);need(owner.visual().receivedPower()==0,"unloaded receiver retired");owner.onLoad();NativeRedstoneChannels.flush(w);need(owner.visual().receivedPower()==15,"local reload queues membership");NativeRedstoneChannels.unregister(source);w.setBlock(SAVE.north(),Blocks.AIR.defaultBlockState(),18);owner.queueInputRefresh();NativeRedstoneChannels.flush(w);need(owner.visual().physicalPower()==0,"deferred neighbor input withdrawal");w.setBlock(SAVE.north(),probe.defaultBlockState(),18);owner.queueInputRefresh();NativeRedstoneChannels.flush(w);
  var edge=new BlockPos(191999,84,191999);Host cold=put(w,edge,false,new CompoundTag());var east=edge.east();need(w.getChunkSource().getChunkNow(east.getX()>>4,east.getZ()>>4)==null,"fresh cold adjacent chunk");cold.onLoad();NativeRedstoneChannels.flush(w);need(w.getChunkSource().getChunkNow(east.getX()>>4,east.getZ()>>4)==null,"deferred host sampling keeps adjacent chunk cold");w.setBlock(edge,Blocks.AIR.defaultBlockState(),18);
  owner.getPersistentData().putString("DeletedRampPlatformField","old");owner.setComponents(net.minecraft.core.component.DataComponentMap.builder().set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("old component")).build());var platform=owner.saveWithoutMetadata(w.registryAccess());owner.loadWithComponents(platform,w.registryAccess());owner.getPersistentData().remove("DeletedRampPlatformField");owner.setComponents(net.minecraft.core.component.DataComponentMap.EMPTY);var deleted=owner.saveWithoutMetadata(w.registryAccess());need(!deleted.getCompound("NeoForgeData").contains("DeletedRampPlatformField")&&!deleted.contains("components"),"platform deletion cannot resurrect retained fields");
  String[] failures={"{ControllerVersion:99}","{NativeRampSchema:99}","{NativeRampPlacementRecovery:1b}","{RampRecoverySnapshot:{PrivateOwner:1b}}","{Sources:[{Pos:1L,PrivateInventory:{Count:1b}}]}","{Sources:\"future\"}","{Cells:[{Pos:1L}]}","{RampSourceTiles:[{Pos:1L,Tile:{Items:[{id:\"future:owner\",Count:1b}]}}]}","{RecoveryPending:1b}","{Moving:1b}","{OriginalState:\"future:block\"}","{Original:{Name:\"minecraft:air\",OpaqueOwner:{Count:1b}}}","{ForgeCaps:{UnknownOwner:\"retained\"}}","{ForgeData:{VandorTransmitters:{main:{Count:0b,OpaqueOwner:1b}}}}","{components:{\"future:owner\":{Count:1}}}"};
  CompoundTag last=null;for(String text:failures){var raw=TagParser.parseTag(text);raw.putString("PrivateRampMarker","sealed");Host failed=put(w,INERT,false,raw);need(failed.inert()&&failed.getRedstoneChannels().isEmpty(),"unsupported ownership/future runtime sealed "+text);need(failed.saveWithoutMetadata(w.registryAccess()).equals(raw),"exact failed snapshot "+text);var recovery=failed.recoverySnapshot();need(recovery.equals(raw),"defensive recovery projection");recovery.putBoolean("mutated",true);need(!failed.recoverySnapshot().contains("mutated"),"recovery projection does not own retained tag");try{failed.itemSettings();throw new AssertionError("inert ordinary item choices");}catch(IllegalStateException expected){}need(!failed.getUpdateTag(w.registryAccess()).toString().contains("sealed"),"inert projection privacy");last=raw;}
  need(last!=null,"inert persisted owner");for(var pos:new BlockPos[]{SAVE,INERT})w.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);
 }
 private static void read(ServerLevel w){NativeRampAuthorizationChecks.read(w);Host owner=at(w,SAVE);need(owner!=null&&!owner.inert()&&owner.slab()&&owner.settings().channels().equals(ChannelList.of(73101)),"saved usable settings owner");need(owner.saveWithoutMetadata(w.registryAccess()).getByteArray("OpaqueRampPayload").length==65536,"saved opaque successful fields");Host failed=at(w,INERT);need(failed!=null&&failed.inert()&&failed.saveWithoutMetadata(w.registryAccess()).getString("PrivateRampMarker").equals("sealed")&&failed.saveWithoutMetadata(w.registryAccess()).contains("components"),"failed opaque owner survives restart");}
 @SubscribeEvent public static void start(ServerStartedEvent event)throws Exception{if(!enabled())return;var w=event.getServer().overworld();observing=true;boolean read=System.getProperty("vandorlabs.transmitterPhase").endsWith("read");if(read)read(w);else write(w);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][ramp-host] "+(read?"read":"write")+" PASS checks="+checks+" inactive foundation only");event.getServer().halt(false);}
